11	// Author: Zhang, Qi
12	// Description:
13	
14	`timescale 1ns/1ns
15	`include "define.v"
16	
17	module axi4lite_2_cta #(
18	  parameter AXILITE_ADDR_WIDTH   = 32,
19	  parameter AXILITE_DATA_WIDTH   = 32,
20	  parameter AXILITE_PROT_WIDTH   = 3 ,
21	  parameter AXILITE_RESP_WIDTH   = 2 ,  
22	  parameter AXILITE_STRB_WIDTH   = 4  
23	  )
24	  (
25	  input                           clk                                             ,
26	  input                           rst_n                                           ,
27	
28	  //cta to axi
29	  output                          host_rsp_ready_o                                ,
30	  input                           host_rsp_valid_i                                ,
31	  input  [`WG_ID_WIDTH-1:0]       host_rsp_inflight_wg_buffer_host_wf_done_wg_id_i,
32	
33	  //axi to cta
34	  input                           host_req_ready_i                                ,
35	  output                          host_req_valid_o                                ,
36	  output [`WG_ID_WIDTH-1:0]       host_req_wg_id_o                                ,
37	  output [`WF_COUNT_WIDTH-1:0]    host_req_num_wf_o                               ,
38	  output [`WAVE_ITEM_WIDTH-1:0]   host_req_wf_size_o                              ,
39	  output [`MEM_ADDR_WIDTH-1:0]    host_req_start_pc_o                             ,
40	  output [`WG_SIZE_X_WIDTH*3-1:0] host_req_kernel_size_3d_o                       ,
41	  output [`MEM_ADDR_WIDTH-1:0]    host_req_pds_baseaddr_o                         ,
42	  output [`MEM_ADDR_WIDTH-1:0]    host_req_csr_knl_o                              ,
43	  output [`VGPR_ID_WIDTH:0]       host_req_vgpr_size_total_o                      ,
44	  output [`SGPR_ID_WIDTH:0]       host_req_sgpr_size_total_o                      ,
45	  output [`LDS_ID_WIDTH:0]        host_req_lds_size_total_o                       ,
46	  output [`GDS_ID_WIDTH:0]        host_req_gds_size_total_o                       ,
47	  output [`VGPR_ID_WIDTH:0]       host_req_vgpr_size_per_wf_o                     ,
48	  output [`SGPR_ID_WIDTH:0]       host_req_sgpr_size_per_wf_o                     ,
49	  output [`MEM_ADDR_WIDTH-1:0]    host_req_gds_baseaddr_o                         ,
50	
51	  output                          s_axilite_awready_o                             ,
52	  input                           s_axilite_awvalid_i                             ,
53	  input  [AXILITE_ADDR_WIDTH-1:0] s_axilite_awaddr_i                              ,
54	  input  [AXILITE_PROT_WIDTH-1:0] s_axilite_awprot_i                              ,
55	
56	  output                          s_axilite_wready_o                              ,
57	  input                           s_axilite_wvalid_i                              ,
58	  input  [AXILITE_DATA_WIDTH-1:0] s_axilite_wdata_i                               ,
59	  input  [AXILITE_STRB_WIDTH-1:0] s_axilite_wstrb_i                               ,
60	
61	  input                           s_axilite_bready_i                              ,
62	  output                          s_axilite_bvalid_o                              ,
63	  output [AXILITE_RESP_WIDTH-1:0] s_axilite_bresp_o                               ,
64	
65	  output                          s_axilite_arready_o                             ,
66	  input                           s_axilite_arvalid_i                             ,
67	  input  [AXILITE_ADDR_WIDTH-1:0] s_axilite_araddr_i                              ,
68	  input  [AXILITE_PROT_WIDTH-1:0] s_axilite_arprot_i                              ,
69	
70	  input                           s_axilite_rready_i                              ,
71	  output [AXILITE_DATA_WIDTH-1:0] s_axilite_rdata_o                               ,
72	  output [AXILITE_RESP_WIDTH-1:0] s_axilite_rresp_o                               ,
73	  output                          s_axilite_rvalid_o                               
74	  );
75	  
76	  localparam NUM_REG = 18;
77	
78	  localparam IDLE      = 5'b00000,
79	             READADDR  = 5'b00001,
80	             READDATA  = 5'b00010,
81	             WRITEADDR = 5'b00100,
82	             WRITEDATA = 5'b01000,
83	             WRITERESP = 5'b10000;
84	
85	  localparam OUT_IDLE  = 1'b0,
86	             OUT_OUTPUT= 1'b1;
87	
88	  reg [NUM_REG*AXILITE_DATA_WIDTH-1:0] data_buf;
89	  reg [AXILITE_DATA_WIDTH-1:0] data_out;
90	
91	  reg awready,wready,bvalid,arready,rvalid;
92	
93	  reg [AXILITE_ADDR_WIDTH-1:0] addr;
94	  reg write;
95	  wire [AXILITE_DATA_WIDTH-1:0] rdata;
96	  reg [AXILITE_DATA_WIDTH-1:0] rdata_reg;
97	
98	  reg s_axilite_rready_r,rvalid_r;
99	
100	  reg [4:0] state;
101	  reg out_state;
102	
103	  always @(posedge clk or negedge rst_n) begin
104	    if(!rst_n) begin
105	      out_state <= OUT_IDLE;
106	    end 
107	    else begin
108	      case(out_state)
109	        OUT_IDLE   : if(data_buf[0]) begin
110	                       out_state <= OUT_OUTPUT;
111	                     end 
112	                     else begin
113	                       out_state <= out_state;
114	                     end 
115	        OUT_OUTPUT : if(host_req_valid_o && host_req_ready_i) begin
116	                       out_state <= OUT_IDLE;
117	                     end 
118	                     else begin
119	                       out_state <= out_state;
120	                     end 
121	        default    : out_state <= out_state; 
122	      endcase
123	    end 
124	  end 
125	
126	  always @(posedge clk or negedge rst_n) begin
127	    if(!rst_n) begin
128	      state <= IDLE;
129	      arready <= 1'b0;
130	      rvalid <= 1'b0;
131	      awready <= 1'b0;
132	      write <= 1'b0;
133	      wready <= 1'b0;
134	      bvalid <= 1'b0;
135	      addr <= 'b0;
136	      data_out <= 'b0;
137	    end 
138	    else begin
139	      case(state)
140	        IDLE      : begin
141	                      rvalid <= 1'b0;
142	                      bvalid <= 1'b0;
143	                      write <= 1'b0;
144	                      if(s_axilite_awvalid_i && (out_state == OUT_IDLE)) begin
145	                        state <= WRITEADDR;
146	                      end
147	                      else if(s_axilite_arvalid_i) begin
148	                        state <= READADDR;
149	                      end 
150	                      else begin
151	                        state <= IDLE;
152	                      end 
153	                    end
154	        READADDR  : begin
155	                      if(s_axilite_arvalid_i && s_axilite_arready_o/*arready*/) begin
156	                        state <= READDATA;
157	                        arready <= 1'b0;
158	                        addr <= s_axilite_araddr_i[AXILITE_ADDR_WIDTH-1:2];
159	                      end
160	                      else begin
161	                        state <= READADDR;
162	                        arready <= 1'b1;
163	                        addr <= addr;
164	                      end 
165	                    end
166	        READDATA  : begin
167	                      if(s_axilite_rready_i && s_axilite_rvalid_o) begin
168	                        state <= IDLE;
169	                        rvalid <= 1'b0;
170	                      end 
171	                      else begin
172	                        state <= READDATA;
173	                        rvalid <= 1'b1;
174	                      end 
175	                    end
176	        WRITEADDR : begin
177	                      if(s_axilite_awvalid_i && s_axilite_awready_o/*awready*/) begin
178	                        state <= WRITEDATA;
179	                        awready <= 1'b0;
180	                        addr <= s_axilite_awaddr_i[AXILITE_ADDR_WIDTH-1:2];
181	                      end
182	                      else begin
183	                        state <= WRITEADDR;
184	                        awready <= 1'b1;
185	                        addr <= addr;
186	                      end 
187	                    end
188	        WRITEDATA : begin
189	                      if(s_axilite_wvalid_i && s_axilite_wready_o/*wready*/) begin
190	                        state <= WRITERESP;
191	                        data_out <= s_axilite_wdata_i;
192	                        write <= 1'b1;
193	                        wready <= 1'b0;
194	                      end
195	                      else begin
196	                        state <= WRITEDATA;
197	                        data_out <= data_out;
198	                        write <= write;
199	                        wready <= 1'b1;
200	                      end 
201	                    end
202	        WRITERESP : begin
203	                      if(s_axilite_bready_i && s_axilite_bvalid_o/*bvalid*/) begin
204	                        state <= IDLE;
205	                        write <= 1'b0;
206	                        bvalid <= 1'b0;
207	                      end 
208	                      else begin
209	                        state <= WRITERESP;
210	                        write <= 1'b0;
211	                        bvalid <= 1'b1;
212	                      end
213	                    end
214	        default   : begin
215	                      state <= IDLE;
216	                    end 
217	      endcase
218	    end 
219	  end 
220	
221	  always @(posedge clk or negedge rst_n) begin
222	    if(!rst_n) begin
223	      s_axilite_rready_r <= 1'b0;
224	      rvalid_r <= 1'b0;
225	    end 
226	    else begin
227	      s_axilite_rready_r <= s_axilite_rready_i;
228	      rvalid_r <= rvalid;
229	    end 
230	  end 
231	
232	  assign host_rsp_ready_o = host_rsp_valid_i && (data_buf[17*AXILITE_DATA_WIDTH]==1'd0);
233	
234	  always @(posedge clk or negedge rst_n) begin
235	    if(!rst_n) begin
236	      rdata_reg <= 'h0;
237	    end 
238	    else begin
239	      rdata_reg <= rdata;
240	    end 
241	  end 
242	
243	  assign rdata = (s_axilite_rready_r || (!rvalid_r)) ? data_buf[((addr+1)*AXILITE_DATA_WIDTH-1)-:AXILITE_DATA_WIDTH] : rdata_reg;
244	
245	  assign s_axilite_rdata_o = rdata;
246	  assign s_axilite_awready_o = awready;
247	  assign s_axilite_wready_o = wready;
248	  assign s_axilite_bvalid_o = bvalid;
249	  assign s_axilite_bresp_o = 2'b0;
250	  assign s_axilite_arready_o = arready;
251	  assign s_axilite_rvalid_o = rvalid;
252	  assign s_axilite_rresp_o = 2'b0;
253	
254	  assign host_req_valid_o = data_buf[0] && (out_state == OUT_OUTPUT);
255	  assign host_req_wg_id_o = data_buf[(1+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];           
256	  assign host_req_num_wf_o = data_buf[(2+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];         
257	  assign host_req_wf_size_o = data_buf[(3+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];        
258	  assign host_req_start_pc_o = data_buf[(4+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];       
259	  assign host_req_vgpr_size_total_o = data_buf[(5+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH]; 
260	  assign host_req_sgpr_size_total_o = data_buf[(6+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];   
261	  assign host_req_lds_size_total_o = data_buf[(7+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];        
262	  assign host_req_gds_size_total_o = 'b0;
263	  assign host_req_vgpr_size_per_wf_o = data_buf[(8+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];
264	  assign host_req_sgpr_size_per_wf_o = data_buf[(9+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH]; 
265	  assign host_req_gds_baseaddr_o = data_buf[(10+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH]; 
266	  assign host_req_pds_baseaddr_o = data_buf[(11+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];
267	  assign host_req_csr_knl_o = data_buf[(12+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH]; 
268	  assign host_req_kernel_size_3d_o[(`WG_SIZE_X_WIDTH*(0+1)-1)-:`WG_SIZE_X_WIDTH] = data_buf[(13+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];   
269	  assign host_req_kernel_size_3d_o[(`WG_SIZE_X_WIDTH*(1+1)-1)-:`WG_SIZE_X_WIDTH] = data_buf[(14+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];   
270	  assign host_req_kernel_size_3d_o[(`WG_SIZE_X_WIDTH*(2+1)-1)-:`WG_SIZE_X_WIDTH] = data_buf[(15+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH];   
271	
272	  always @(posedge clk or negedge rst_n) begin
273	    if(!rst_n) begin
274	      data_buf <= 'b0;
275	    end 
276	    else if(host_rsp_valid_i && (!data_buf[17*AXILITE_DATA_WIDTH])) begin
277	      data_buf[(17+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH] <= 'b1;
278	      data_buf[(16+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH] <= host_rsp_inflight_wg_buffer_host_wf_done_wg_id_i;
279	    end
280	    else if((state==READDATA)&&(addr==17)&&data_buf[17*AXILITE_DATA_WIDTH]&&(rvalid==1'd1)) begin
281	      data_buf[(17+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH] <= 'b0;
282	    end 
283	    else if((out_state == OUT_OUTPUT) && host_req_ready_i && host_req_valid_o) begin
284	      data_buf[(0+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH] <= 'b0;
285	    end 
286	    else if(write) begin
287	      data_buf[(addr+1)*AXILITE_DATA_WIDTH-1 -: AXILITE_DATA_WIDTH] <= data_out;
288	    end 
289	    else begin
290	      data_buf <= data_buf;
291	    end 
292	  end 
293	
294	endmodule
