11	// Author: Zhang, Qi
12	// Description:
13	
14	module axi4_adapter #(
15	  parameter int unsigned DATA_WIDTH             = 64 ,
16	  // the AXI subsystem needs to support wrapping reads for this feature
17	  parameter logic        CRITICAL_WORD_FIRST    = 0  , 
18	  parameter int unsigned CACHELINE_BYTE_OFFSET  = 3  ,
19	  parameter int unsigned MAX_OUTSTANDING_STORES = 0  ,
20	
21	  // AXI types
22	  parameter int unsigned AXI_ADDR_WIDTH         = 32 ,
23	  parameter int unsigned AXI_DATA_WIDTH         = 64 ,
24	  parameter int unsigned AXI_ID_WIDTH           = 4  ,
25	  parameter int unsigned AXI_LEN_WIDTH          = 8  ,
26	  parameter int unsigned AXI_SIZE_WIDTH         = 3  ,
27	  parameter int unsigned AXI_BURST_WIDTH        = 2  ,
28	  parameter int unsigned AXI_CACHE_WIDTH        = 4  ,
29	  parameter int unsigned AXI_PROT_WIDTH         = 3  ,
30	  parameter int unsigned AXI_QOS_WIDTH          = 4  ,
31	  parameter int unsigned AXI_REGION_WIDTH       = 4  ,
32	  parameter int unsigned AXI_USER_WIDTH         = 32 ,
33	  parameter int unsigned AXI_ATOP_WIDTH         = 6  ,
34	  parameter int unsigned AXI_RESP_WIDTH         = 2  ,
35	
36	  parameter type axi_req_t = logic,
37	  parameter type axi_rsp_t = logic
38	  ) 
39	  (
40	  input  logic                                                           clk_i                ,  
41	  input  logic                                                           rst_ni               , 
42	
43	  output logic                                                           busy_o               ,
44	  input  logic                                                           req_i                ,
45	  input  logic                                                           type_i               ,
46	  input  logic [3:0]                                                     amo_i                ,
47	  output logic                                                           gnt_o                ,
48	  input  logic [AXI_ADDR_WIDTH-1:0]                                      addr_i               ,
49	  input  logic                                                           we_i                 ,
50	  input  logic [(DATA_WIDTH/AXI_DATA_WIDTH)-1:0][AXI_DATA_WIDTH-1:0]     wdata_i              ,
51	  input  logic [(DATA_WIDTH/AXI_DATA_WIDTH)-1:0][(AXI_DATA_WIDTH/8)-1:0] be_i                 ,
52	  input  logic [2:0]                                                     size_i               ,
53	  input  logic [AXI_ID_WIDTH-1:0]                                        id_i                 ,
54	  // read port
55	  output logic                                                           valid_o              ,
56	  output logic [(DATA_WIDTH/AXI_DATA_WIDTH)-1:0][AXI_DATA_WIDTH-1:0]     rdata_o              ,
57	  output logic [AXI_ID_WIDTH-1:0]                                        id_o                 ,
58	  // critical word - read port
59	  output logic [AXI_DATA_WIDTH-1:0]                                      critical_word_o      ,
60	  output logic                                                           critical_word_valid_o,
61	  // AXI port
62	  output axi_req_t                                                       axi_req_o            ,
63	  input  axi_rsp_t                                                       axi_resp_i
64	  );
65	  
66	  //req type
67	  localparam SINGLE_REQ     = 0;
68	  localparam CACHE_LINE_REQ = 1;
69	
70	  localparam BURST_SIZE = (DATA_WIDTH / AXI_DATA_WIDTH) - 1;
71	
72	  localparam BURST_FIXED = 2'b00;
73	  localparam BURST_INCR  = 2'b01;
74	  localparam BURST_WRAP  = 2'b10;
75	
76	  localparam RESP_OKAY   = 2'b00;
77	  localparam RESP_EXOKAY = 2'b01;
78	  localparam RESP_SLVERR = 2'b10;
79	  localparam RESP_DECERR = 2'b11;
80	
81	  localparam CACHE_BUFFERABLE = 4'b0001;
82	  localparam CACHE_MODIFIABLE = 4'b0010;
83	  localparam CACHE_RD_ALLOC   = 4'b0100;
84	  localparam CACHE_WR_ALLOC   = 4'b1000;
85	
86	  localparam ATOP_ATOMICSWAP  = 6'b110000;
87	  localparam ATOP_ATOMICCMP   = 6'b110001;
88	  localparam ATOP_NONE        = 2'b00;
89	  localparam ATOP_ATOMICSTORE = 2'b01;
90	  localparam ATOP_ATOMICLOAD  = 2'b10;
91	  localparam ATOP_LITTLE_END  = 1'b0;
92	  localparam ATOP_BIG_END     = 1'b1;
93	  localparam ATOP_ADD         = 3'b000;
94	  localparam ATOP_CLR         = 3'b001;
95	  localparam ATOP_EOR         = 3'b010;
96	  localparam ATOP_SET         = 3'b011;
97	  localparam ATOP_SMAX        = 3'b100;
98	  localparam ATOP_SMIN        = 3'b101;
99	  localparam ATOP_UMAX        = 3'b110;
100	  localparam ATOP_UMIN        = 3'b111;
101	  localparam ATOP_R_RESP      = 32'd5;
102	
103	  localparam ADDR_INDEX = ($clog2(DATA_WIDTH/AXI_DATA_WIDTH) > 0) ? $clog2(DATA_WIDTH/AXI_DATA_WIDTH) : 1;
104	
105	  localparam MAX_OUTSTANDING_AW = MAX_OUTSTANDING_STORES;
106	
107	  localparam MAX_OUTSTANDING_AW_CNT_WIDTH = $clog2(MAX_OUTSTANDING_AW+1) > 0 ? $clog2(MAX_OUTSTANDING_AW+1) : 1;
108	
109	  typedef logic [MAX_OUTSTANDING_AW_CNT_WIDTH-1:0] outstanding_aw_cnt_t;
110	
111	  enum logic [3:0] {
112	    IDLE,
113	    WAIT_B_VALID,
114	    WAIT_AW_READY,
115	    WAIT_LAST_W_READY,
116	    WAIT_LAST_W_READY_AW_READY,
117	    WAIT_AW_READY_BURST,
118	    WAIT_R_VALID,
119	    WAIT_R_VALID_MULTIPLE,
120	    COMPLETE_READ,
121	    WAIT_AMO_R_VALID
122	  } state_q, state_d;
123	
124	  // counter for AXI transfers
125	  logic [ADDR_INDEX-1:0] cnt_d, cnt_q;
126	  logic [(DATA_WIDTH/AXI_DATA_WIDTH)-1:0][AXI_DATA_WIDTH-1:0] cache_line_d, cache_line_q;
127	  // save the address for a read, as we allow for non-cacheline aligned accesses
128	  logic [(DATA_WIDTH/AXI_DATA_WIDTH)-1:0] addr_offset_d, addr_offset_q;
129	  logic [AXI_ID_WIDTH-1:0] id_d, id_q;
130	  logic [ADDR_INDEX-1:0] index;
131	
132	  // save the atomic operation and size
133	  typedef enum logic [3:0] {
134	    AMO_NONE = 4'b0000,
135	    AMO_LR   = 4'b0001,
136	    AMO_SC   = 4'b0010,
137	    AMO_SWAP = 4'b0011,
138	    AMO_ADD  = 4'b0100,
139	    AMO_AND  = 4'b0101,
140	    AMO_OR   = 4'b0110,
141	    AMO_XOR  = 4'b0111,
142	    AMO_MAX  = 4'b1000,
143	    AMO_MAXU = 4'b1001,
144	    AMO_MIN  = 4'b1010,
145	    AMO_MINU = 4'b1011,
146	    AMO_CAS1 = 4'b1100,  // unused, not part of riscv spec, but provided in OpenPiton
147	    AMO_CAS2 = 4'b1101   // unused, not part of riscv spec, but provided in OpenPiton
148	  } amo_t;
149	
150	  logic [3:0] amo_d,amo_q;
151	
152	  logic [1:0] size_d, size_q;
153	  // outstanding write transactions counter
154	  outstanding_aw_cnt_t outstanding_aw_cnt_q, outstanding_aw_cnt_d;
155	  logic any_outstanding_aw;
156	
157	  assign any_outstanding_aw = outstanding_aw_cnt_q != '0;
158	
159	  // Busy if we're not idle
160	  assign busy_o = state_q != IDLE;
161	
162	  always_comb begin : axi_fsm
163	    // Default assignments
164	    axi_req_o.aw_valid  = 1'b0;
165	    // Cast to AXI address width
166	    axi_req_o.aw.addr   = addr_i;
167	    axi_req_o.aw.prot   = 3'b0;
168	    axi_req_o.aw.region = 4'b0;
169	    axi_req_o.aw.len    = 8'b0;
170	    axi_req_o.aw.size   = size_i;  // 1, 2, 4 or 8 bytes
171	    axi_req_o.aw.burst  = BURST_INCR;  // Use BURST_INCR for AXI regular transaction
172	    axi_req_o.aw.lock   = 1'b0;
173	    axi_req_o.aw.cache  = CACHE_MODIFIABLE;
174	    axi_req_o.aw.qos    = 4'b0;
175	    axi_req_o.aw.id     = id_i;
176	    axi_req_o.aw.atop   = atop_from_amo(amo_i);
177	    axi_req_o.aw.user   = '0;
178	
179	    axi_req_o.ar_valid  = 1'b0;
180	    // Cast to AXI address width
181	    axi_req_o.ar.addr   = addr_i;
182	    // in case of a single request or wrapping transfer we can simply begin at the address, if we want to request a cache-line
183	    // with an incremental transfer we need to output the corresponding base address of the cache line
184	    if (!CRITICAL_WORD_FIRST && type_i != SINGLE_REQ) begin
185	      axi_req_o.ar.addr[CACHELINE_BYTE_OFFSET-1:0] = '0;
186	    end
187	    axi_req_o.ar.prot = 3'b0;
188	    axi_req_o.ar.region = 4'b0;
189	    axi_req_o.ar.len = 8'b0;
190	    axi_req_o.ar.size = {1'b0, size_i};  // 1, 2, 4 or 8 bytes
191	    axi_req_o.ar.burst  = (CRITICAL_WORD_FIRST ? BURST_WRAP : BURST_INCR); // wrapping transfer in case of a critical word first strategy
192	    axi_req_o.ar.lock = 1'b0;
193	    axi_req_o.ar.cache = CACHE_MODIFIABLE;
194	    axi_req_o.ar.qos = 4'b0;
195	    axi_req_o.ar.id = id_i;
196	    axi_req_o.ar.user = '0;
197	
198	    axi_req_o.w_valid = 1'b0;
199	    axi_req_o.w.data = wdata_i[0];
200	    axi_req_o.w.strb = be_i[0];
201	    axi_req_o.w.last = 1'b0;
202	    axi_req_o.w.user = '0;
203	
204	    axi_req_o.b_ready = 1'b0;
205	    axi_req_o.r_ready = 1'b0;
206	
207	    gnt_o = 1'b0;
208	    valid_o = 1'b0;
209	    id_o = axi_resp_i.r.id;
210	
211	    critical_word_o = axi_resp_i.r.data;
212	    critical_word_valid_o = 1'b0;
213	    rdata_o = cache_line_q;
214	
215	    state_d = state_q;
216	    cnt_d = cnt_q;
217	    cache_line_d = cache_line_q;
218	    addr_offset_d = addr_offset_q;
219	    id_d = id_q;
220	    amo_d = amo_q;
221	    size_d = size_q;
222	    index = '0;
223	
224	    outstanding_aw_cnt_d = outstanding_aw_cnt_q;
225	
226	    case (state_q)
227	
228	      IDLE: begin
229	        cnt_d = '0;
230	        // we have an incoming request
231	        if (req_i) begin
232	          // is this a read or write?
233	          // write
234	          if (we_i) begin
235	            // multiple outstanding write transactions are only
236	            // allowed if they are guaranteed not to be reordered
237	            // i.e. same ID
238	            if (!any_outstanding_aw || ((id_i == id_q) && (amo_i == AMO_NONE))) begin
239	              // the data is valid
240	              axi_req_o.aw_valid = 1'b1;
241	              axi_req_o.w_valid  = 1'b1;
242	              // store-conditional requires exclusive access
243	              axi_req_o.aw.lock  = amo_i == AMO_SC;
244	              // its a single write
245	              if (type_i == SINGLE_REQ) begin
246	                // only a single write so the data is already the last one
247	                axi_req_o.w.last = 1'b1;
248	                // single req can be granted here
249	                gnt_o = axi_resp_i.aw_ready & axi_resp_i.w_ready;
250	                case ({
251	                  axi_resp_i.aw_ready, axi_resp_i.w_ready
252	                })
253	                  2'b11:   state_d = WAIT_B_VALID;
254	                  2'b01:   state_d = WAIT_AW_READY;
255	                  2'b10:   state_d = WAIT_LAST_W_READY;
256	                  default: state_d = IDLE;
257	                endcase
258	
259	                if (axi_resp_i.aw_ready) begin
260	                  id_d   = id_i;
261	                  amo_d  = amo_i;
262	                  size_d = size_i;
263	                end
264	
265	                // its a request for the whole cache line
266	              end else begin
267	                // bursts of AMOs unsupported
268	                //assert (amo_i == AMO_NONE)
269	                //else $fatal("Bursts of atomic operations are not supported");
270	
271	                axi_req_o.aw.len = BURST_SIZE[7:0];  // number of bursts to do
272	                axi_req_o.w.data = wdata_i[0];
273	                axi_req_o.w.strb = be_i[0];
274	
275	                if (axi_resp_i.w_ready) cnt_d = BURST_SIZE[ADDR_INDEX-1:0] - 1;
276	                else cnt_d = BURST_SIZE[ADDR_INDEX-1:0];
277	
278	                case ({
279	                  axi_resp_i.aw_ready, axi_resp_i.w_ready
280	                })
281	                  2'b11:   state_d = WAIT_LAST_W_READY;
282	                  2'b01:   state_d = WAIT_LAST_W_READY_AW_READY;
283	                  2'b10:   state_d = WAIT_LAST_W_READY;
284	                  default: ;
285	                endcase
286	              end
287	            end
288	            // read
289	          end else begin
290	            // only multiple outstanding write transactions are allowed
291	            if (!any_outstanding_aw) begin
292	
293	              axi_req_o.ar_valid = 1'b1;
294	              // load-reserved requires exclusive access
295	              axi_req_o.ar.lock = amo_i == AMO_LR;
296	
297	              gnt_o = axi_resp_i.ar_ready;
298	              if (type_i != SINGLE_REQ) begin
299	                //assert (amo_i == AMO_NONE)
300	                //else $fatal("Bursts of atomic operations are not supported");
301	
302	                axi_req_o.ar.len = BURST_SIZE[7:0];
303	                cnt_d = BURST_SIZE[ADDR_INDEX-1:0];
304	              end
305	
306	              if (axi_resp_i.ar_ready) begin
307	                state_d = (type_i == SINGLE_REQ) ? WAIT_R_VALID : WAIT_R_VALID_MULTIPLE;
308	                addr_offset_d = addr_i[ADDR_INDEX-1+3:3];
309	              end
310	            end
311	          end
312	        end
313	      end
314	
315	      // ~> from single write
316	      WAIT_AW_READY: begin
317	        axi_req_o.aw_valid = 1'b1;
318	
319	        if (axi_resp_i.aw_ready) begin
320	          gnt_o   = 1'b1;
321	          state_d = WAIT_B_VALID;
322	          id_d    = id_i;
323	          amo_d   = amo_i;
324	          size_d  = size_i;
325	        end
326	      end
327	
328	      // ~> we need to wait for an aw_ready and there is at least one outstanding write
329	      WAIT_LAST_W_READY_AW_READY: begin
330	        axi_req_o.w_valid = 1'b1;
331	        axi_req_o.w.last  = (cnt_q == '0);
332	        if (type_i == SINGLE_REQ) begin
333	          axi_req_o.w.data = wdata_i[0];
334	          axi_req_o.w.strb = be_i[0];
335	        end else begin
336	          axi_req_o.w.data = wdata_i[BURST_SIZE[ADDR_INDEX-1:0]-cnt_q];
337	          axi_req_o.w.strb = be_i[BURST_SIZE[ADDR_INDEX-1:0]-cnt_q];
338	        end
339	        axi_req_o.aw_valid = 1'b1;
340	        // we are here because we want to write a cache line
341	        axi_req_o.aw.len   = BURST_SIZE[7:0];
342	        // we got an aw_ready
343	        case ({
344	          axi_resp_i.aw_ready, axi_resp_i.w_ready
345	        })
346	          // we got an aw ready
347	          2'b01: begin
348	            // are there any outstanding transactions?
349	            if (cnt_q == 0) state_d = WAIT_AW_READY_BURST;
350	            else  // yes, so reduce the count and stay here
351	              cnt_d = cnt_q - 1;
352	          end
353	          2'b10:   state_d = WAIT_LAST_W_READY;
354	          2'b11: begin
355	            // we are finished
356	            if (cnt_q == 0) begin
357	              state_d = WAIT_B_VALID;
358	              gnt_o   = 1'b1;
359	              // there are outstanding transactions
360	            end else begin
361	              state_d = WAIT_LAST_W_READY;
362	              cnt_d   = cnt_q - 1;
363	            end
364	          end
365	          default: ;
366	        endcase
367	
368	      end
369	
370	      // ~> all data has already been sent, we are only waiting for the aw_ready
371	      WAIT_AW_READY_BURST: begin
372	        axi_req_o.aw_valid = 1'b1;
373	        axi_req_o.aw.len   = BURST_SIZE[7:0];
374	
375	        if (axi_resp_i.aw_ready) begin
376	          state_d = WAIT_B_VALID;
377	          gnt_o   = 1'b1;
378	        end
379	      end
380	
381	      // ~> from write, there is an outstanding write
382	      WAIT_LAST_W_READY: begin
383	        axi_req_o.w_valid = 1'b1;
384	
385	        if (type_i != SINGLE_REQ) begin
386	          axi_req_o.w.data = wdata_i[BURST_SIZE[ADDR_INDEX-1:0]-cnt_q];
387	          axi_req_o.w.strb = be_i[BURST_SIZE[ADDR_INDEX-1:0]-cnt_q];
388	        end
389	
390	        // this is the last write
391	        if (cnt_q == '0) begin
392	          axi_req_o.w.last = 1'b1;
393	          if (axi_resp_i.w_ready) begin
394	            state_d = WAIT_B_VALID;
395	            gnt_o   = 1'b1;
396	          end
397	        end else if (axi_resp_i.w_ready) begin
398	          cnt_d = cnt_q - 1;
399	        end
400	      end
401	
402	      // ~> finish write transaction
403	      WAIT_B_VALID: begin
404	        id_o = axi_resp_i.b.id;
405	
406	        // Write is valid
407	        if (axi_resp_i.b_valid && !any_outstanding_aw) begin
408	          axi_req_o.b_ready = 1'b1;
409	
410	          // some atomics must wait for read data
411	          // we only accept it after accepting bvalid
412	          if (amo_returns_data(amo_q)) begin
413	            if (axi_resp_i.r_valid) begin
414	              // return read data if valid
415	              valid_o           = 1'b1;
416	              axi_req_o.r_ready = 1'b1;
417	              state_d           = IDLE;
418	              rdata_o           = axi_resp_i.r.data;
419	            end else begin
420	              // wait otherwise
421	              state_d = WAIT_AMO_R_VALID;
422	            end
423	          end else begin
424	            valid_o = 1'b1;
425	            state_d = IDLE;
426	
427	            // store-conditional response
428	            if (amo_q == AMO_SC) begin
429	              if (axi_resp_i.b.resp == RESP_EXOKAY) begin
430	                // success -> return 0
431	                rdata_o = 'b0;
432	              end else begin
433	                // failure -> when request is 64-bit, return 1;
434	                // when request is 32-bit place a 1 in both upper
435	                // and lower half words. The right word will be
436	                // realigned/masked externally
437	                rdata_o = size_q == 2'b10 ? (1'b1 << 32) | 64'b1 : 64'b1;
438	              end
439	            end
440	          end
441	          // if the request was not an atomic we can possibly issue
442	          // other requests while waiting for the response
443	        end else begin
444	          if ((amo_q == AMO_NONE) && (outstanding_aw_cnt_q != MAX_OUTSTANDING_AW)) begin
445	            state_d = IDLE;
446	            outstanding_aw_cnt_d = outstanding_aw_cnt_q + 1;
447	          end
448	        end
449	      end
450	
451	      // ~> some atomics wait for read data
452	      WAIT_AMO_R_VALID: begin
453	        // acknowledge data and terminate atomic
454	        if (axi_resp_i.r_valid) begin
455	          axi_req_o.r_ready = 1'b1;
456	          state_d           = IDLE;
457	          valid_o           = 1'b1;
458	          rdata_o           = axi_resp_i.r.data;
459	        end
460	      end
461	
462	      // ~> cacheline read, single read
463	      WAIT_R_VALID_MULTIPLE, WAIT_R_VALID: begin
464	        if (CRITICAL_WORD_FIRST) index = addr_offset_q + (BURST_SIZE[ADDR_INDEX-1:0] - cnt_q);
465	        else index = BURST_SIZE[ADDR_INDEX-1:0] - cnt_q;
466	
467	        // reads are always wrapping here
468	        axi_req_o.r_ready = 1'b1;
469	        // this is the first read a.k.a the critical word
470	        if (axi_resp_i.r_valid) begin
471	          if (CRITICAL_WORD_FIRST) begin
472	            // this is the first word of a cacheline read, e.g.: the word which was causing the miss
473	            if (state_q == WAIT_R_VALID_MULTIPLE && cnt_q == BURST_SIZE) begin
474	              critical_word_valid_o = 1'b1;
475	              critical_word_o       = axi_resp_i.r.data;
476	            end
477	          end else begin
478	            // check if the address offset matches - then we are getting the critical word
479	            if (index == addr_offset_q) begin
480	              critical_word_valid_o = 1'b1;
481	              critical_word_o       = axi_resp_i.r.data;
482	            end
483	          end
484	
485	          // this is the last read
486	          if (axi_resp_i.r.last) begin
487	            id_d    = axi_resp_i.r.id;
488	            state_d = COMPLETE_READ;
489	          end
490	
491	          // save the word
492	          if (state_q == WAIT_R_VALID_MULTIPLE) begin
493	            cache_line_d[index] = axi_resp_i.r.data;
494	
495	          end else cache_line_d[0] = axi_resp_i.r.data;
496	
497	          // Decrease the counter
498	          cnt_d = cnt_q - 1;
499	        end
500	      end
501	      // ~> read is complete
502	      COMPLETE_READ: begin
503	        valid_o = 1'b1;
504	        state_d = IDLE;
505	        id_o    = id_q;
506	      end
507	
508	      default: state_d = IDLE;
509	    endcase
510	
511	    // This process handles B responses when accepting
512	    // multiple outstanding write transactions
513	    if (any_outstanding_aw && axi_resp_i.b_valid) begin
514	      axi_req_o.b_ready = 1'b1;
515	      valid_o = 1'b1;
516	      // Right hand side contains non-registered signal as we want
517	      // to preserve a possible increment from the WAIT_B_VALID state
518	      outstanding_aw_cnt_d = outstanding_aw_cnt_d - 1;
519	    end
520	  end
521	
522	  // ----------------
523	  // Registers
524	  // ----------------
525	  always_ff @(posedge clk_i or negedge rst_ni) begin
526	    if (~rst_ni) begin
527	      // start in flushing state and initialize the memory
528	      state_q              <= IDLE;
529	      cnt_q                <= '0;
530	      cache_line_q         <= '0;
531	      addr_offset_q        <= '0;
532	      id_q                 <= '0;
533	      amo_q                <= AMO_NONE;
534	      size_q               <= '0;
535	      outstanding_aw_cnt_q <= '0;
536	    end else begin
537	      state_q              <= state_d;
538	      cnt_q                <= cnt_d;
539	      cache_line_q         <= cache_line_d;
540	      addr_offset_q        <= addr_offset_d;
541	      id_q                 <= id_d;
542	      amo_q                <= amo_d;
543	      size_q               <= size_d;
544	      outstanding_aw_cnt_q <= outstanding_aw_cnt_d;
545	    end
546	  end
547	
548	  function automatic logic [AXI_ATOP_WIDTH-1:0] atop_from_amo(logic [3:0] amo);
549	    logic [AXI_ATOP_WIDTH-1:0] result = 6'b000000;
550	
551	    unique case (amo)
552	      AMO_NONE: result = {ATOP_NONE, 4'b0000};
553	      AMO_SWAP: result = {ATOP_ATOMICSWAP};
554	      AMO_ADD:
555	      result = {ATOP_ATOMICLOAD, ATOP_LITTLE_END, ATOP_ADD};
556	      AMO_AND:
557	      result = {ATOP_ATOMICLOAD, ATOP_LITTLE_END, ATOP_CLR};
558	      AMO_OR:
559	      result = {ATOP_ATOMICLOAD, ATOP_LITTLE_END, ATOP_SET};
560	      AMO_XOR:
561	      result = {ATOP_ATOMICLOAD, ATOP_LITTLE_END, ATOP_EOR};
562	      AMO_MAX:
563	      result = {ATOP_ATOMICLOAD, ATOP_LITTLE_END, ATOP_SMAX};
564	      AMO_MAXU:
565	      result = {ATOP_ATOMICLOAD, ATOP_LITTLE_END, ATOP_UMAX};
566	      AMO_MIN:
567	      result = {ATOP_ATOMICLOAD, ATOP_LITTLE_END, ATOP_SMIN};
568	      AMO_MINU:
569	      result = {ATOP_ATOMICLOAD, ATOP_LITTLE_END, ATOP_UMIN};
570	      AMO_CAS1: result = {ATOP_NONE, 4'b0000};  // Unsupported
571	      AMO_CAS2: result = {ATOP_NONE, 4'b0000};  // Unsupported
572	      default: result = 6'b000000;
573	    endcase
574	
575	    return result;
576	  endfunction
577	
578	  function automatic logic amo_returns_data(logic [3:0] amo);
579	    logic [AXI_ATOP_WIDTH-1:0] atop = atop_from_amo(amo);
580	    logic           is_load = atop[5:4] == ATOP_ATOMICLOAD;
581	    logic           is_swap_or_cmp = atop[5:4] == ATOP_ATOMICSWAP[5:4];
582	    return is_load || is_swap_or_cmp;
583	  endfunction
584	
585	endmodule
586

